"""Small digital filter module: moving average and first-order IIR lowpass."""

import math
from typing import List, Sequence


def moving_average(x: Sequence[float], M: int) -> List[float]:
    """Causal moving average of the last M samples (zero-padded history)."""
    if M <= 0:
        raise ValueError("M must be positive")
    out = []
    acc = 0.0
    for n, v in enumerate(x):
        acc += v
        if n >= M:
            acc -= x[n - M]
        out.append(acc / M)
    return out


def iir_lowpass_coeff(dt: float, RC: float) -> float:
    """Alpha coefficient for y[n] = a*x[n] + (1-a)*y[n-1]."""
    return dt / (RC + dt)


def iir_lowpass(x: Sequence[float], a: float, y0: float = 0.0) -> List[float]:
    """First-order IIR lowpass: y[n] = a*x[n] + (1-a)*y[n-1]."""
    out = []
    y = y0
    for v in x:
        y = a * v + (1.0 - a) * y
        out.append(y)
    return out


def design_fc(fs: float, fc: float):
    """Return (dt, RC, a) for sampling rate fs and cutoff fc."""
    dt = 1.0 / fs
    RC = 1.0 / (2.0 * math.pi * fc)
    return dt, RC, iir_lowpass_coeff(dt, RC)

